def prime_factors(x, small_primes):
    fs = set()
    y = x
    for p in small_primes:
        if p * p > y:
            break
        if y % p == 0:
            fs.add(p)
            while y % p == 0:
                y //= p
    if y > 1:
        fs.add(y)
    return fs


